package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaElDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("Allahumma Bika Asbahna", "Ω Αλλάχ, με Σένα μπαίνουμε στο πρωί και με Σένα μπαίνουμε στο βράδυ. δι' εσένα ζούμε και δι' Εσένα πεθαίνουμε, και σε Σένα είναι η ανάσταση.", "Το πρωί.", "Ο Προφήτης ﷺ δίδαξε τους συντρόφους να λένε σήμερα το πρωί και το βράδυ."),
        "dua_allahumma_bika_amsayna" to DuaText("Allahumma Bika Amsayna", "Ω Αλλάχ, με Σένα μπαίνουμε στο βράδυ και με Σένα μπαίνουμε στο πρωί. από Σένα ζούμε και από Σένα πεθαίνουμε, και σε Σένα είναι η επιστροφή.", "Το βράδυ.", "Ο Προφήτης ﷺ δίδαξε τους συντρόφους να λένε σήμερα το πρωί και το βράδυ."),
        "dua_afiyah_morning" to DuaText("Ζητώντας την Afiyah", "Ω Αλλάχ, Σου ζητώ συγγνώμη και ευημερία σε αυτόν τον κόσμο και στο εξής.", "Ο Προφήτης ﷺ δεν άφησε ποτέ αυτή τη ντουά, πρωί ή βράδυ.", "Σε κανέναν δεν έχει δοθεί κάτι καλύτερο από την ευημερία."),
        "dua_afini_fi_badani" to DuaText("Υγεία σώματος, ακοής και όρασης", "Ω Αλλάχ, δώσε ευεξία στο σώμα μου. Ω Αλλάχ, δώσε ευημερία στην ακοή μου. Ω Αλλάχ, δώσε ευεξία στα μάτια μου. Δεν υπάρχει θεός εκτός από Εσένα.", "Τρεις φορές κάθε πρωί και βράδυ.", "Μια ντουά για την υγεία και την προστασία των αισθήσεων."),
        "dua_ya_hayyu_aslih" to DuaText("Διορθώστε όλες τις υποθέσεις μου", "Ω Αιώνια Ζωντανή, Ω Συντηρήτρια, με το έλεός Σου ζητώ βοήθεια: Διορθώστε όλες τις υποθέσεις μου και μην με αφήνετε στον εαυτό μου ούτε μια ριπή οφθαλμού.", "Ο Προφήτης ﷺ συμβούλεψε τη Φατιμά (RA) να το λέει πρωί και βράδυ.", "Ζητώντας τη βοήθεια του Αλλάχ σε κάθε θέμα."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Τασμπίχ της Τζουουαϊρίγια (RA)", "Δόξα να είναι ο Αλλάχ και κάθε έπαινος είναι δικός Του - όσο το δημιούργημά Του, όσο τον ευχαριστεί, ίσο με το βάρος του Θρόνου Του και το μελάνι των λόγων Του.", "Τρεις φορές το πρωί — πιο βαρύ από τις ώρες του dhikr.", "Το να πεις αυτές τις τέσσερις φράσεις τρεις φορές υπερτερεί του ντικρ από την αυγή μέχρι τα μεσάνυχτα."),
        "dua_salawat" to DuaText("Durood-e-Ibrahimi", "Ω Αλλάχ, στείλε προσευχές στον Μωάμεθ ﷺ και στην οικογένεια του Μωάμεθ όπως έστειλες προσευχές στον Ιμπραήμ (AS) και στην οικογένεια του Ιμπραήμ. Είσαι Αξιέπαινος, Ένδοξος. Ω Αλλάχ, ευλόγησε τον Μωάμεθ ﷺ και την οικογένεια του Μωάμεθ όπως ευλόγησες τον Ιμπραήμ (AS) και την οικογένεια του Ιμπραήμ. Είσαι Αξιέπαινος, Ένδοξος.", "Salawat στον Προφήτη ﷺ στην προσευχή και ανά πάσα στιγμή.", "Όποιος στέλνει σαλαβάτ μια φορά, ο Αλλάχ στέλνει δέκα ελέη πάνω του (Μουσουλμ. 408)."),
        "dua_wudu_after" to DuaText("Μετά το Wudu", "Καταθέτω μαρτυρία ότι κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, τον Μοναδικό, που δεν έχει κανέναν εταίρο, και ότι ο Μωάμεθ ﷺ είναι υπηρέτης και αγγελιοφόρος Του. Ω Αλλάχ, κάνε με ανάμεσα σε αυτούς που μετανοούν και σε αυτούς που εξαγνίζονται.", "Μετά την ολοκλήρωση της wudu.", "Οι οκτώ πύλες του Παραδείσου ανοίγονται για να μπει από όποιον θέλει."),
        "dua_wudu_before" to DuaText("Πριν το Wudu", "Στο όνομα του Αλλάχ.", "Όταν ξεκινάμε wudu.", "Δεν υπάρχει (πλήρη) wudu για κάποιον που δεν αναφέρει το όνομα του Αλλάχ από πάνω."),
        "dua_istiftah" to DuaText("Παράκληση έναρξης (Sana)", "Δόξα σε Σένα, Ω Αλλάχ, και δόξα σε Σένα. Ευλογημένο το όνομά Σου, υψωμένο το μεγαλείο Σου, και δεν υπάρχει θεός εκτός από Σένα.", "Στην αρχή της προσευχής, αμέσως μετά το εναρκτήριο takbir.", "Η Σούννα έναρξης ντουέτα της προσευχής."),
        "dua_ruku" to DuaText("Στο Ρούκου", "Δόξα στον Κύριό μου, τον Μεγαλοπρεπή.", "Τουλάχιστον τρεις φορές στο ρούκου.", "Το Sunnah tasbih του ρούκου."),
        "dua_sujood" to DuaText("Στο Sujood", "Δόξα στον Κύριό μου, τον Ύψιστο.", "Τουλάχιστον τρεις φορές σε sujood.", "Ο υπηρέτης είναι πιο κοντά στον Κύριό του ενώ βρίσκεται σε υπόκλιση (Μουσουλμάνος 482)."),
        "dua_rising_ruku" to DuaText("Ανατέλλει από το Ruku", "Ο Αλλάχ ακούει αυτόν που Τον επαινεί. Κύριε μας, σε Σένα ανήκει κάθε έπαινος.", "Ενώ σηκώνεσαι από το ρούκου και στέκεσαι όρθιος.", "Όποιος το 'Rabbana wa lakal-hamd' συμπίπτει με αυτό των αγγέλων, οι προηγούμενες αμαρτίες του συγχωρούνται."),
        "dua_between_sajdas" to DuaText("Ανάμεσα στα Δύο Sajdas", "Κύριε μου, συγχώρεσέ με. Κύριε μου, συγχώρεσέ με.", "Ενώ κάθεται ανάμεσα στις δύο προσκυνήσεις.", "Η Sunnah ντουέτα του καθίσματος μεταξύ των προσκυνήσεων."),
        "dua_before_salam_four" to DuaText("Καταφύγιο από τέσσερα πράγματα (πριν από το Salam)", "Ω Αλλάχ, αναζητώ καταφύγιο σε Σένα από την τιμωρία της κόλασης, από την τιμωρία του τάφου, από τις δοκιμασίες της ζωής και του θανάτου και από το κακό της δοκιμασίας του Ψεύτικου Μεσσία (Dajjal).", "Μετά το τελικό tashahhud και salawat, πριν το σαλάμ.", "Ο Προφήτης ﷺ διέταξε να αναζητήσουν καταφύγιο από αυτά τα τέσσερα πράγματα."),
        "dua_qunoot_witr" to DuaText("Qunoot στο Witr", "Ω Αλλάχ, καθοδήγησέ με ανάμεσα σε αυτούς που οδήγησες, δώσε μου ευημερία ανάμεσα σε αυτούς που χάρισες ευημερία, πάρε με στη φροντίδα Σου ανάμεσα σε αυτούς που έχεις αναλάβει στη φροντίδα Σου, ευλόγησέ με σε ό,τι έχεις δώσει και προστάτεψε με από το κακό όσων έχεις ορίσει. Εσύ διατάσσεις και κανένας δεν διατάσσει εναντίον Σου, και αυτός με τον οποίο είσαι φίλος δεν ταπεινώνεται ποτέ. Ευλογημένος και Υψηλός είσαι, Κύριε μας.", "Στην προσευχή του witr — ο Προφήτης ﷺ τη δίδαξε στον Hasan ibn Ali (RA).", "Το Sunnah qunoot του witr. (Μεταξύ των Χαναφί, το 'Allahumma inna nasta'inuka' είναι επίσης πολύ γνωστό.)"),
        "dua_qunoot_hanafi" to DuaText("Qunoot (Allahumma Inna Nasta'inuka)", "Ω Αλλάχ, ζητάμε τη βοήθειά Σου και τη συγχώρεση Σου, πιστεύουμε σε Σένα και στηριζόμαστε σε Σένα, Σε επαινούμε με τον καλύτερο τρόπο, Σε ευχαριστούμε και δεν είμαστε αχάριστοι, και εγκαταλείπουμε όποιον Σε παρακούει. Ω Αλλάχ, Εσένα μόνο λατρεύουμε, σε Σένα προσευχόμαστε και προσκυνούμε, προς Σένα σπεύδουμε και αγωνιζόμαστε, ελπίζουμε στο έλεός Σου και φοβόμαστε την τιμωρία Σου. σίγουρα η τιμωρία Σου θα φτάσει στους άπιστους.", "In witr — η πρακτική των Χαναφί.", "Αναφέρθηκε από το Umar (RA) στο qunoot."),
        "dua_sleep_aslamtu" to DuaText("Τελευταία λόγια πριν τον ύπνο", "Ω Αλλάχ, υποτάσσομαι σε Σένα, εμπιστεύομαι την υπόθεσή μου σε Σένα και δεσμεύω την πλάτη μου στην προστασία Σου, από ελπίδα σε Σένα και από φόβο σε Σένα. Δεν υπάρχει καταφύγιο και διαφυγή από Σένα παρά μόνο σε Εσένα. Πιστεύω στο Βιβλίο Σου που αποκάλυψες και στον Προφήτη Σου που έστειλες.", "Μετά την wudu, ξαπλωμένη στη δεξιά πλευρά - οι τελευταίες λέξεις πριν από τον ύπνο.", "Αν πεθάνει εκείνη τη νύχτα, πεθαίνει κατά τη φίτρα (Ισλάμ)."),
        "dua_waking_night" to DuaText("Ξύπνημα τη νύχτα", "Κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, τον Μοναδικό, που δεν έχει κανέναν εταίρο. Δική του είναι η κυριαρχία και δικός του είναι ο έπαινος, και έχει δύναμη πάνω σε όλα τα πράγματα. Όλος ο έπαινος είναι για τον Αλλάχ, δόξα να είναι ο Αλλάχ, κανείς δεν είναι άξιος λατρείας εκτός από τον Αλλάχ, ο Αλλάχ είναι ο Μεγαλύτερος, και δεν υπάρχει ισχύς ούτε δύναμη εκτός από τον Αλλάχ. Ω Αλλάχ, συγχώρεσέ με.", "Στο ξύπνημα κατά τη διάρκεια της νύχτας.", "Η προσευχή του απαντάται, και αν κάνει wudu και προσεύχεται, η προσευχή του γίνεται δεκτή."),
        "dua_hamm_ibn_masud" to DuaText("Dua for Grief (Ιμπν Μασούντ)", "Ω Αλλάχ, είμαι ο υπηρέτης Σου, ο γιος του δούλου Σου, ο γιος της υπηρέτριας Σου. Το μπροστινό μου μπροστινό μέρος είναι στο χέρι Σου, η εντολή Σου πάνω μου εκτελείται, και το διάταγμά Σου για εμένα είναι δίκαιο. Σε παρακαλώ με κάθε όνομα που είναι δικό σου, με το οποίο ονόμασες τον εαυτό σου, ή αποκαλύφθηκες στο Βιβλίο Σου, ή δίδαξες σε οποιοδήποτε δημιούργημά Σου, ή κράτησες μαζί σου στη γνώση του αόρατου - να κάνεις το Κοράνι την πηγή της καρδιάς μου, το φως του στήθους μου, την απομάκρυνση της λύπης μου και την αναχώρηση της ανησυχίας μου.", "Σε θλίψη και στενοχώρια - ο Αλλάχ αντικαθιστά τη θλίψη με χαρά.", "Ο Αλλάχ αφαιρεί την ανησυχία και τη θλίψη του και του δίνει χαρά στη θέση του."),
        "dua_difficulty_sahl" to DuaText("Όταν κάτι είναι δύσκολο", "Ω Αλλάχ, τίποτα δεν είναι εύκολο εκτός από αυτό που κάνεις εύκολο, και τα δύσκολα τα κάνεις εύκολα αν θέλεις.", "Όταν κάτι είναι δύσκολο.", "Ευκολία στις εξετάσεις και στις δύσκολες εργασίες."),
        "dua_musibah" to DuaText("Πάνω σε μια συμφορά (Istirja)", "Ανήκουμε στον Αλλάχ και σε Αυτόν θα επιστρέψουμε. Ω Αλλάχ, ανταμείψέ με στη θλίψη μου και αντικατάστησέ μου με κάτι καλύτερο.", "Σε οποιαδήποτε απώλεια ή συμφορά.", "Ο Αλλάχ σίγουρα δίνει κάτι καλύτερο - στην Ουμ Σαλαμά (RA) δόθηκε στον Προφήτη ﷺ."),
        "dua_debt" to DuaText("Για την απαλλαγή από το χρέος", "Ω Αλλάχ, αρκεσέ με με ό,τι έχεις κάνει νόμιμο ενάντια σε αυτό που έκανες παράνομο, και με τη γενναιοδωρία Σου κάνε με ανεξάρτητο από όλους εκτός από Σένα.", "Για την εξόφληση του χρέους — διδάσκεται από τον Ali (RA).", "Ακόμα κι αν το χρέος είναι σαν βουνό, ο Αλλάχ θα το τακτοποιήσει."),
        "dua_anger" to DuaText("Όταν θυμωμένος", "Αναζητώ καταφύγιο στον Αλλάχ από τον Σαϊτάν, τον καταραμένο.", "Όταν θυμώνει.", "Ο Προφήτης ﷺ είπε: αν το πει αυτό, ο θυμός του θα φύγει."),
        "dua_waswasa" to DuaText("Ενάντια στη Waswasa in Faith", "Πιστεύω στον Αλλάχ και στους αγγελιοφόρους Του.", "Όταν έρχονται σατανικοί ψίθυροι για πίστη.", "Όταν έρθει ο ψίθυρος, πείτε αυτό και σταματήστε εκεί (και επίσης αναζητήστε καταφύγιο στον Αλλάχ)."),
        "dua_travel_full" to DuaText("Πλήρης Ταξιδιωτική Παράκληση", "Ω Αλλάχ, Σου ζητάμε σε αυτό το ταξίδι δικαιοσύνη και ευσέβεια και πράξεις που σε ευχαριστούν. Ω Αλλάχ, κάνε μας εύκολο αυτό το ταξίδι και μείωσε την απόστασή του. Ω Αλλάχ, είσαι ο σύντροφος στο ταξίδι και ο φύλακας της οικογένειας.", "Όταν ξεκινάτε ένα ταξίδι, μετά το «Subhanalladhi sakhkhara».", "Η πλήρης ντουέτα ταξιδιού Sunnah."),
        "dua_return_travel" to DuaText("Επιστρέφοντας από τα ταξίδια", "Επιστρέφουμε, μετανοούμε, προσκυνούμε και δοξάζουμε τον Κύριό μας.", "Επιστρέφοντας από ένα ταξίδι.", "Ο Προφήτης ﷺ το είπε αυτό επιστρέφοντας από ένα ταξίδι."),
        "dua_farewell_traveller" to DuaText("Αποχαιρετώντας έναν Ταξιδιώτη", "Εμπιστεύομαι στον Αλλάχ τη θρησκεία σου, την εμπιστοσύνη σου και το αποτέλεσμα των πράξεών σου.", "Όταν αποχαιρετούν έναν ταξιδιώτη.", "Ό,τι έχει ανατεθεί στον Αλλάχ δεν χάνεται ποτέ."),
        "dua_entering_town" to DuaText("Στάση σε ένα μέρος", "Αναζητώ καταφύγιο στα τέλεια λόγια του Αλλάχ από το κακό όλων όσων δημιούργησε.", "Όταν σταματάτε σε ένα μέρος ή φτάνετε σε μια νέα πόλη.", "Τίποτα δεν θα τον βλάψει μέχρι να φύγει από εκεί."),
        "dua_boarding_ship" to DuaText("Επιβίβαση σε πλοίο / όχημα", "Στο όνομα του Αλλάχ είναι η πλεύση και η αγκυροβόλησή του. Πράγματι, ο Κύριός μου είναι συγχωρητικός, ελεήμων.", "Όταν επιβιβάζεστε σε πλοίο ή όχημα — τα λόγια του Προφήτη Nuh (AS).", "Ένας στίχος Κορανίου — η ντουά της κιβωτού του Nuh (AS)."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Ιστιγκφάρ με τον Χαγιούλ-Καγιούμ", "Ζητώ συγχώρεση από τον Αλλάχ, εκτός από τον οποίο δεν υπάρχει θεός, τον Αιώνια Ζωντανό, τον Συντηρητή, και στρέφομαι σε Αυτόν με μετάνοια.", "Για μετάνοια.", "Οι αμαρτίες του συγχωρούνται ακόμα κι αν είχε φύγει από το πεδίο της μάχης."),
        "dua_rabbighfir_warham" to DuaText("Rabbighfir Warham", "Κύριε μου, συγχώρεσε και ελέησε, γιατί είσαι ο καλύτερος από αυτούς που δείχνουν έλεος.", "Μια κορανική ντουέτα - για συγχώρεση και έλεος.", "Ο τελευταίος στίχος της Σούρας αλ-Μουμίνουν."),
        "dua_majlis_kaffarah" to DuaText("Kaffarat al-Majlis", "Δόξα σε Σένα, Ω Αλλάχ, και δόξα σε Σένα. Δίνω μαρτυρία ότι δεν υπάρχει θεός εκτός από Εσένα. Ζητώ τη συγχώρεση Σου και στρέφομαι σε Σένα με μετάνοια.", "Όταν σηκώνεσαι από μια συγκέντρωση.", "Γίνεται εξιλέωση για ό,τι λάθος ειπώθηκε στη συγκέντρωση."),
        "dua_jami_forgiveness" to DuaText("Ολοκληρωμένη Συγχώρεση", "Ω Αλλάχ, συγχώρεσε με τα λάθη μου, την άγνοιά μου, την υπερβολή μου στις υποθέσεις μου και όλα όσα ξέρεις καλύτερα από εμένα.", "Μια περιεκτική ντουέτα του Προφήτη ﷺ.", "Ο Προφήτης ﷺ συνήθιζε να κάνει αυτή τη ντουά."),
        "dua_parents_nuh" to DuaText("Dua of Nuh (AS) για γονείς", "Κύριε μου, συγχώρεσέ με, τους γονείς μου, όποιον μπαίνει στο σπίτι μου ως πιστός, και όλους τους πιστούς άνδρες και τις πιστές γυναίκες.", "Για τους γονείς και τους πιστούς.", "Η ντουά του Προφήτη Νουχ (AS)."),
        "dua_shukr_parents" to DuaText("Ευγνωμοσύνη για Γονείς & Δίκαιους Απόγονους", "Κύριε μου, επέτρεψέ με να είμαι ευγνώμων για την εύνοιά Σου που χάρισες σε μένα και στους γονείς μου, και να κάνω ορθές πράξεις που σε ευχαριστούν και να κάνεις τους απογόνους μου δίκαιους. Στρέφομαι σε Σένα με μετάνοια και είμαι ανάμεσα σε αυτούς που υποτάσσονται.", "Η κορανική ντουέτα της συμπλήρωσης σαράντα ετών.", "Η ευγνωμοσύνη, οι καλές πράξεις και η δικαιοσύνη των παιδιών του - όλα σε μια ντουέτα."),
        "dua_intimacy" to DuaText("Πριν από τις συζυγικές σχέσεις", "Στο όνομα του Αλλάχ. Ω Αλλάχ, κράτα τον Σαϊτάν μακριά από εμάς και κράτα τον Σαϊτάνα μακριά από όσα (παιδιά) μας δίνεις.", "Πριν από τις συζυγικές σχέσεις.", "Εάν ένα παιδί οριστεί, ο Σαϊτάν δεν θα το βλάψει ποτέ."),
        "dua_ibrahim_children_protection" to DuaText("Προστασία Σπίτι και Παιδιού", "Κύριε μου, κάνε αυτή την πόλη ασφαλή και κράτησε εμένα και τα παιδιά μου μακριά από τη λατρεία των ειδώλων.", "Η ντουά του Προφήτη Ιμπραήμ (AS) — για την ασφάλεια της πόλης και των παιδιών του.", "Μια ντουά για να παραμείνετε σταθεροί στο tawhid."),
        "dua_drinking_milk" to DuaText("Όταν πίνετε γάλα", "Ω Αλλάχ, ευλόγησέ το για εμάς και δώσε μας περισσότερα από αυτό.", "Όταν πίνετε γάλα.", "Το γάλα αρκεί και ως τροφή και ως ποτό."),
        "dua_iftar_host" to DuaText("Όταν διακόπτετε τη νηστεία με άλλους", "Είθε οι νηστευτές να κόψουν τη νηστεία τους μαζί σας, οι δίκαιοι να φάνε το φαγητό σας και οι άγγελοι να προσεύχονται για εσάς.", "Όταν σπάει τη νηστεία στο σπίτι κάποιου.", "Η ντουέτα του Προφήτη ﷺ για τον οικοδεσπότη."),
    )
}
